ALTER TABLE public.consent_text_versions ADD COLUMN approval_reference text, ADD COLUMN approved_at timestamptz, ADD COLUMN document_url text;
COMMENT ON COLUMN public.consent_text_versions.approval_reference IS 'Verified owner/counsel approval provenance; existing generic consent wording is not approved by inference. Server-owned.';
ALTER TABLE public.events ADD COLUMN platform_agreement_en uuid REFERENCES public.consent_text_versions(id), ADD COLUMN platform_agreement_es uuid REFERENCES public.consent_text_versions(id);
ALTER TABLE public.waiver_library ADD COLUMN file_path text, ADD COLUMN file_name text, ADD COLUMN is_default boolean NOT NULL DEFAULT false;
ALTER TABLE public.waiver_library_versions ADD COLUMN file_path text, ADD COLUMN file_name text;
CREATE UNIQUE INDEX host_waiver_one_default ON public.waiver_library(owner_id) WHERE is_default AND NOT archived;
CREATE TABLE public.platform_event_acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES public.events(id) ON DELETE CASCADE,rsvp_id uuid NOT NULL REFERENCES public.rsvps(id) ON DELETE CASCADE,document_id uuid NOT NULL REFERENCES public.consent_text_versions(id),content_sha256 text NOT NULL,user_id uuid,accepted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(rsvp_id,document_id));
GRANT SELECT ON public.platform_event_acceptances TO authenticated; GRANT ALL ON public.platform_event_acceptances TO service_role;
ALTER TABLE public.platform_event_acceptances ENABLE ROW LEVEL SECURITY;
CREATE POLICY platform_acceptance_self ON public.platform_event_acceptances FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER platform_acceptance_immutable BEFORE UPDATE ON public.platform_event_acceptances FOR EACH ROW EXECUTE FUNCTION public.block_history_rewrite();
CREATE OR REPLACE FUNCTION public.approved_event_agreement(_locale text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM consent_text_versions WHERE kind='terms' AND team_id IS NULL AND locale=_locale AND approved_at IS NOT NULL AND length(trim(approval_reference))>0 AND document_url ~ '^https://' AND effective_from<=now() ORDER BY version DESC,created_at DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.approved_event_agreement(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.approved_event_agreement(text) TO service_role;
CREATE OR REPLACE FUNCTION public.event_platform_agreement(_event uuid,_token text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e events;en consent_text_versions;es consent_text_versions; BEGIN PERFORM unlock_invite(_event,_token); IF public.get_public_event(_event) IS NULL AND NOT public.can_manage_event(_event) THEN RETURN NULL; END IF; SELECT * INTO e FROM events WHERE id=_event;SELECT * INTO en FROM consent_text_versions WHERE id=coalesce(e.platform_agreement_en,approved_event_agreement('en'));SELECT * INTO es FROM consent_text_versions WHERE id=coalesce(e.platform_agreement_es,approved_event_agreement('es')); RETURN jsonb_build_object('ready',en.id IS NOT NULL AND es.id IS NOT NULL,'en_id',en.id,'es_id',es.id,'en_url',en.document_url,'es_url',es.document_url,'en_version',en.version,'es_version',es.version); END $$;
REVOKE ALL ON FUNCTION public.event_platform_agreement(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.event_platform_agreement(uuid,text) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pin_platform_event_agreement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.platform_agreement_en,NEW.platform_agreement_es) IS DISTINCT FROM (OLD.platform_agreement_en,OLD.platform_agreement_es) THEN RAISE EXCEPTION 'agreement_pinned'; END IF; IF NEW.status='published' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'published') THEN NEW.platform_agreement_en:=coalesce(NEW.platform_agreement_en,approved_event_agreement('en')); NEW.platform_agreement_es:=coalesce(NEW.platform_agreement_es,approved_event_agreement('es')); IF NEW.platform_agreement_en IS NULL OR NEW.platform_agreement_es IS NULL THEN RAISE EXCEPTION 'approved_legal_document_required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER events_platform_agreement BEFORE INSERT OR UPDATE OF status,platform_agreement_en,platform_agreement_es ON public.events FOR EACH ROW EXECUTE FUNCTION public.pin_platform_event_agreement();
DROP POLICY IF EXISTS library_managers ON public.waiver_library;CREATE POLICY library_host_owner ON public.waiver_library FOR SELECT TO authenticated USING(owner_id=auth.uid());
DROP POLICY IF EXISTS library_history_managers ON public.waiver_library_versions;CREATE POLICY library_history_host_owner ON public.waiver_library_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM waiver_library w WHERE w.id=waiver_id AND w.owner_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.save_host_waiver(_team uuid,_id uuid,_name text,_en text,_es text,_file text DEFAULT NULL,_filename text DEFAULT NULL,_archive boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w waiver_library;BEGIN IF auth.uid() IS NULL OR NOT team_capability(_team,'events') OR EXISTS(SELECT 1 FROM user_suspensions WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'forbidden';END IF;IF length(trim(_name)) NOT BETWEEN 1 AND 120 OR length(_en)>12000 OR length(_es)>12000 OR (length(trim(_en))=0 AND _file IS NULL) THEN RAISE EXCEPTION 'invalid_waiver';END IF;IF _file IS NOT NULL AND (_file NOT LIKE auth.uid()::text||'/host-waivers/%.pdf' OR _file LIKE '%..%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='media' AND name=_file AND (metadata->>'size')::bigint<=10485760 AND metadata->>'mimetype'='application/pdf')) THEN RAISE EXCEPTION 'invalid_file'; END IF;IF _id IS NULL THEN INSERT INTO waiver_library(team_id,owner_id,name,body_en,body_es,file_path,file_name) VALUES(_team,auth.uid(),trim(_name),trim(_en),trim(_es),_file,left(_filename,120)) RETURNING * INTO w;ELSE SELECT * INTO w FROM waiver_library WHERE id=_id AND owner_id=auth.uid() FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden';END IF;UPDATE waiver_library SET name=trim(_name),body_en=trim(_en),body_es=trim(_es),file_path=_file,file_name=left(_filename,120),version=w.version+CASE WHEN(w.name,w.body_en,w.body_es,w.file_path) IS DISTINCT FROM(trim(_name),trim(_en),trim(_es),_file) THEN 1 ELSE 0 END,archived=_archive,is_default=CASE WHEN _archive THEN false ELSE is_default END,updated_at=now() WHERE id=w.id RETURNING * INTO w;END IF;INSERT INTO waiver_library_versions(waiver_id,version,name,body_en,body_es,content_sha256,file_path,file_name) VALUES(w.id,w.version,w.name,w.body_en,w.body_es,policy_text_sha(concat_ws(chr(31),w.name,w.body_en,w.body_es,w.file_path)),w.file_path,w.file_name) ON CONFLICT DO NOTHING;RETURN w.id;END $$;
REVOKE ALL ON FUNCTION public.save_host_waiver(uuid,uuid,text,text,text,text,text,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_host_waiver(uuid,uuid,text,text,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_library_waiver(_team uuid,_id uuid,_name text,_en text,_es text,_archive boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN save_host_waiver(_team,_id,_name,_en,_es,NULL,NULL,_archive); END $$;
CREATE OR REPLACE FUNCTION public.set_host_waiver_default(_id uuid,_on boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'host-waiver-default',0));IF NOT EXISTS(SELECT 1 FROM waiver_library WHERE id=_id AND owner_id=auth.uid() AND NOT archived) THEN RAISE EXCEPTION 'forbidden';END IF;IF _on THEN UPDATE waiver_library SET is_default=false WHERE owner_id=auth.uid() AND is_default;END IF;UPDATE waiver_library SET is_default=_on WHERE id=_id;END $$;
REVOKE ALL ON FUNCTION public.set_host_waiver_default(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.set_host_waiver_default(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.attach_library_waiver(_event uuid,_waiver uuid,_version int) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e events;w waiver_library;v waiver_library_versions;wid uuid;av int;BEGIN SELECT * INTO e FROM events WHERE id=_event FOR UPDATE;IF e.host_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'forbidden';END IF;SELECT * INTO w FROM waiver_library WHERE id=_waiver AND owner_id=e.host_id AND NOT archived;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden';END IF;SELECT * INTO v FROM waiver_library_versions WHERE waiver_id=w.id AND version=_version;IF NOT FOUND THEN RAISE EXCEPTION 'waiver_stale';END IF;SELECT id,library_version INTO wid,av FROM event_waivers WHERE event_id=e.id AND library_id=w.id AND archived_at IS NULL;IF wid IS NOT NULL AND av=_version THEN RETURN wid;END IF;IF e.status<>'draft' THEN RAISE EXCEPTION 'waiver_pinned';END IF;IF wid IS NOT NULL THEN UPDATE event_waivers SET library_version=v.version,title_en=v.name,title_es=v.name,body_en=v.body_en,body_es=v.body_es,file_path=v.file_path,file_name=v.file_name WHERE id=wid;ELSE INSERT INTO event_waivers(event_id,library_id,library_version,title_en,title_es,body_en,body_es,file_path,file_name,required) VALUES(e.id,w.id,v.version,v.name,v.name,v.body_en,v.body_es,v.file_path,v.file_name,true) RETURNING id INTO wid;END IF;RETURN wid;END $$;
CREATE OR REPLACE FUNCTION public.host_waiver_event_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e events;BEGIN SELECT * INTO e FROM events WHERE id=NEW.event_id;IF auth.uid() IS NOT NULL AND e.host_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'forbidden';END IF;IF e.status<>'draft' THEN IF TG_OP='INSERT' OR (NEW.kind,NEW.title_en,NEW.title_es,NEW.body_en,NEW.body_es,NEW.file_path,NEW.required,NEW.archived_at,NEW.library_version) IS DISTINCT FROM(OLD.kind,OLD.title_en,OLD.title_es,OLD.body_en,OLD.body_es,OLD.file_path,OLD.required,OLD.archived_at,OLD.library_version) THEN RAISE EXCEPTION 'waiver_pinned'; END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER event_waivers_host_pin BEFORE INSERT OR UPDATE ON public.event_waivers FOR EACH ROW EXECUTE FUNCTION public.host_waiver_event_guard();
CREATE OR REPLACE FUNCTION public.legacy_waiver_host_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM teams WHERE id=NEW.team_id AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'forbidden';END IF; RETURN NEW;END $$;
CREATE TRIGGER waivers_host_owner BEFORE UPDATE ON public.waivers FOR EACH ROW EXECUTE FUNCTION public.legacy_waiver_host_guard();
DROP POLICY IF EXISTS team_waiver_managers ON public.waivers;CREATE POLICY legacy_waiver_owner ON public.waivers FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM teams WHERE id=team_id AND owner_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.legacy_waiver_selection_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.requires_waiver IS DISTINCT FROM OLD.requires_waiver THEN IF OLD.status<>'draft' THEN RAISE EXCEPTION 'waiver_pinned'; END IF;IF NEW.requires_waiver THEN RAISE EXCEPTION 'select_host_waiver';END IF;END IF;IF TG_OP='INSERT' AND NEW.requires_waiver THEN RAISE EXCEPTION 'select_host_waiver';END IF;RETURN NEW; END $$;
CREATE TRIGGER events_legacy_waiver_selection BEFORE INSERT OR UPDATE OF requires_waiver ON public.events FOR EACH ROW EXECUTE FUNCTION public.legacy_waiver_selection_guard();
COMMENT ON COLUMN public.events.requires_waiver IS 'Legacy team waiver requirement retained with its pinned historical evidence; new host waivers use event_waivers library snapshots.';
COMMENT ON TABLE public.waivers IS 'Legacy team-scoped documents preserved for historical receipts; new reusable host waivers use waiver_library.owner_id.';